<?php require_once 'config/db.php';$error='';if(isset($_POST['submit'])){$email=mysqli_real_escape_string($conn,trim($_POST['email']));$r=mysqli_query($conn,"SELECT * FROM users WHERE email='$email' AND status='Active' LIMIT 1");$u=mysqli_fetch_assoc($r);if($u && password_verify($_POST['password'],$u['password'])){$_SESSION=['user_id'=>$u['user_id'],'full_name'=>$u['full_name'],'role'=>$u['role']];$to=$u['role']==='Doctor'?'doctor/dashboard.php':($u['role']==='Patient'?'patient/dashboard.php':'admin/dashboard.php');header("Location: $to");exit;}$error='Email or password is incorrect.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in | Care Connect</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-page"><main class="auth-card"><a class="brand" href="index.php">care<span>connect</span></a><p class="eyebrow">WELCOME BACK</p><h1>Sign in to your care.</h1><?php if($error):?><div class="alert alert-error"><?=$error?></div><?php endif;?><form method="post"><div class="field"><label>EMAIL ADDRESS</label><input type="email" name="email" required></div><div class="field"><label>PASSWORD</label><input type="password" name="password" minlength="8" required></div><button class="btn btn-primary" name="submit">Sign in securely</button></form><p class="note">New to Care Connect? <a href="register.php" style="color:#0b8378;font-weight:700">Create your account</a></p></main></body></html>
